"""Small utility nodes that do not depend on the MiniMax H3 implementation."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

import nodes as comfy_nodes


class _AnyType(str):
    # ComfyUI wildcard sockets compare equal to every concrete socket type.
    def __ne__(self, _value: object) -> bool:
        return False


WslAnyType = _AnyType("*")
MAX_MULTI_SET_VALUES = 64


class WyslMiniMaxH3EasyPrompt:
    CATEGORY = "Wsl/工具"
    FUNCTION = "get_prompt"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("提示词",)
    DESCRIPTION = "独立提示词输入节点，可连接到 MiniMax H3 Easy。@ 媒体引用由前端桥接处理。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "prompt": (
                    "STRING",
                    {"multiline": True, "dynamicPrompts": True, "default": ""},
                ),
            }
        }

    @staticmethod
    def get_prompt(prompt):
        return (str(prompt or ""),)


def _select_values(input_values: Mapping[str, Any], count: int) -> tuple[Any, ...]:
    positions: dict[int, int] = {}
    outputs: list[Any] = []
    for index in range(count):
        values = input_values.get(f"value_{index + 1}", [])
        if not isinstance(values, (list, tuple)):
            values = [values]
        if not values:
            outputs.append(None)
            continue
        if len(values) == 1:
            outputs.append(values[0])
            continue
        source_id = id(values)
        source_index = positions.get(source_id, 0)
        if source_index >= len(values):
            raise ValueError("Multi Set 从同一列表输出接出的端口数量超过列表项目数")
        outputs.append(values[source_index])
        positions[source_id] = source_index + 1
    return tuple(outputs)


class WyslMultiSet:
    CATEGORY = "Wsl/工具"
    FUNCTION = "route_values"
    RETURN_TYPES = (WslAnyType,) * MAX_MULTI_SET_VALUES
    RETURN_NAMES = tuple(f"值 {index + 1}" for index in range(MAX_MULTI_SET_VALUES))
    INPUT_IS_LIST = True
    OUTPUT_IS_LIST = (False,) * MAX_MULTI_SET_VALUES
    DESCRIPTION = "收集多个动态类型的值，支持 KJ Get 节点按名称获取。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "optional": {
                f"value_{index + 1}": (WslAnyType, {"forceInput": True})
                for index in range(MAX_MULTI_SET_VALUES)
            }
        }

    @staticmethod
    def route_values(**kwargs):
        return _select_values(kwargs, MAX_MULTI_SET_VALUES)


class WyslMiniMaxH3EasyAreaSwitch:
    CATEGORY = "Wsl/工具"
    FUNCTION = "route"
    RETURN_TYPES = (WslAnyType,)
    RETURN_NAMES = ("选中值",)
    DESCRIPTION = "只执行当前选中的功能区，未选中的输入使用惰性连接。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "use_first": (
                    "BOOLEAN",
                    {"default": True, "label_on": "反推", "label_off": "不反推"},
                ),
                "first_area": ("STRING", {"default": "反推", "multiline": False}),
                "second_area": ("STRING", {"default": "不反推", "multiline": False}),
                "auto_sync": (
                    "BOOLEAN",
                    {"default": True, "label_on": "自动跟随忽略多组", "label_off": "手动控制"},
                ),
            },
            "optional": {
                "first": (WslAnyType, {"lazy": True}),
                "second": (WslAnyType, {"lazy": True}),
            },
        }

    @staticmethod
    def check_lazy_status(use_first, first=None, second=None, **_kwargs):
        selected_name = "first" if bool(use_first) else "second"
        selected_value = first if selected_name == "first" else second
        return [selected_name] if selected_value is None else []

    @staticmethod
    def route(use_first, first=None, second=None, **_kwargs):
        return (first if bool(use_first) else second,)


class WyslSwapDimensions:
    CATEGORY = "Wsl/工具"
    FUNCTION = "swap"
    RETURN_TYPES = ("INT", "INT")
    RETURN_NAMES = ("宽度", "高度")
    DESCRIPTION = "按开关决定是否交换宽度和高度。"

    @classmethod
    def INPUT_TYPES(cls):
        max_resolution = int(getattr(comfy_nodes, "MAX_RESOLUTION", 16384))
        return {
            "required": {
                "width": ("INT", {"default": 1024, "min": 1, "max": max_resolution, "step": 1}),
                "height": ("INT", {"default": 1024, "min": 1, "max": max_resolution, "step": 1}),
                "swap_dimensions": (
                    "BOOLEAN",
                    {"default": False, "label_on": "交换长宽", "label_off": "保持原顺序"},
                ),
            }
        }

    @staticmethod
    def swap(width, height, swap_dimensions=False):
        width, height = int(width), int(height)
        return (height, width) if bool(swap_dimensions) else (width, height)


